// # `async for` calls `__aiter__()`: the second variant
// @dispatch
// def __aiter__(self, x: int32) -> Own[Other]:
//     return Other()
inline Other Source::__aiter____int32(int32_t x) const {
    return Other();
}

inline Other Source::__aiter__(int32_t x) const {
    return this->__aiter____int32(x);
}

// @dispatch
// def __aiter__(self) -> "Source":
//     return self
inline Source& Source::__aiter____noargs() {
    return (*this);
}

inline Source& Source::__aiter__() {
    return this->__aiter____noargs();
}

