inline SyncManager::SyncManager() : log(std::vector<std::string>{}) {}

// # `with` calls `__enter__()`: the second variant
// @dispatch
// def __enter__(self, x: int32) -> int32:
//     self.log.append("enter-x")
//     return 5
inline int32_t SyncManager::__enter____int32(int32_t x) {
    this->log.push_back("enter-x");
    return 5;
}

inline int32_t SyncManager::__enter__(int32_t x) {
    return this->__enter____int32(x);
}

// @dispatch
// def __enter__(self) -> int32:
//     self.log.append("enter")
//     return 7
inline int32_t SyncManager::__enter____noargs() {
    this->log.push_back("enter");
    return 7;
}

inline int32_t SyncManager::__enter__() {
    return this->__enter____noargs();
}

